-- Production seed migration for Civitai image-label training.
-- Contains 51 safe, prompted image records with downloaded image paths.
-- Run from the project root with: psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f server/src/sql/production-civitai-training.sql
-- Also deploy civitai_collector/data/images/ unchanged; PostgreSQL does not store the image bytes.
BEGIN;

CREATE TABLE IF NOT EXISTS images (
  id BIGSERIAL PRIMARY KEY,
  civitai_id BIGINT UNIQUE NOT NULL,
  post_id BIGINT,
  creator_id BIGINT,
  creator_username TEXT,
  source_url TEXT NOT NULL,
  local_path TEXT,
  width INTEGER,
  height INTEGER,
  nsfw_level TEXT,
  type TEXT,
  blurhash TEXT,
  prompt TEXT,
  negative_prompt TEXT,
  model_name TEXT,
  model_version_id BIGINT,
  sampler TEXT,
  steps INTEGER,
  cfg_scale DOUBLE PRECISION,
  seed BIGINT,
  created_at TIMESTAMPTZ,
  sha256 CHAR(64) UNIQUE,
  metadata JSONB,
  downloaded BOOLEAN NOT NULL DEFAULT FALSE,
  download_error TEXT,
  discovered_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_images_post_id ON images(post_id);
CREATE INDEX IF NOT EXISTS idx_images_model_version ON images(model_version_id);
CREATE INDEX IF NOT EXISTS idx_images_creator ON images(creator_username);
CREATE INDEX IF NOT EXISTS idx_images_sha256 ON images(sha256);
CREATE INDEX IF NOT EXISTS idx_images_metadata ON images USING GIN(metadata);

INSERT INTO images (civitai_id, post_id, creator_id, creator_username, source_url, local_path, width, height, nsfw_level, type, blurhash, prompt, negative_prompt, model_name, model_version_id, sampler, steps, cfg_scale, seed, created_at, sha256, metadata, downloaded, download_error, discovered_at, updated_at) VALUES
(144082237, 31296986, NULL, 'BeeZ333', 'https://image.civitai.com/xG1nkqKTMzGDvpLrqFT7WA/a69d29c9-5adb-4873-b301-56467c69748b/original=true/a69d29c9-5adb-4873-b301-56467c69748b.jpeg', 'civitai_collector/data/images/144082237.webp', 768, 1376, 'None', 'image', 'U9E.Is|[00TfOw?G+sD+000z^*^j9q4:OZ^*', '@NJSW33T,zidiusArt,A poignant surreal fantasy illustration of magical realism, portraying the awakening from a dream. The surrounding world is an impossibly vibrant, luminous celestial dreamscape: a blooming wildflower meadow by a reflective lake, glowing pink-orange sunset clouds, and an indigo cosmos filled with a radiant golden crescent moon and sparkling Milky Way galaxy. In the corner, a miniature girl gently pulls back a heavy curtain woven from the starry night sky itself. Drawing back this celestial curtain reveals the cold, quiet truth of reality: a minimalist, monochromatic plain grey room with a bare concrete wall and empty space, completely devoid of color. Dramatic emotional contrast between the breathtaking saturated fantasy and the quiet, somber grey waking world, poetic storybook aesthetic, masterpiece digital painting.', NULL, NULL, NULL, 'euler', 8, 1, 1251833571, '2026-09-28T16:05:00.000Z'::timestamptz, '4a7e6b51a15dcd1ce2a0926114096dc30210da8acd2986cf815159ca1befe9e6', '{"seed":1251833571,"extra":{},"steps":8,"width":768,"height":1376,"prompt":"@NJSW33T,zidiusArt,A poignant surreal fantasy illustration of magical realism, portraying the awakening from a dream. The surrounding world is an impossibly vibrant, luminous celestial dreamscape: a blooming wildflower meadow by a reflective lake, glowing pink-orange sunset clouds, and an indigo cosmos filled with a radiant golden crescent moon and sparkling Milky Way galaxy. In the corner, a miniature girl gently pulls back a heavy curtain woven from the starry night sky itself. Drawing back this celestial curtain reveals the cold, quiet truth of reality: a minimalist, monochromatic plain grey room with a bare concrete wall and empty space, completely devoid of color. Dramatic emotional contrast between the breathtaking saturated fantasy and the quiet, somber grey waking world, poetic storybook aesthetic, masterpiece digital painting.","sampler":"euler","cfgScale":1,"priority":"low","quantity":1,"workflow":"txt2img","ecosystem":"Krea2","resources":[],"resolution":"1K","aspectRatio":{"value":"9:16","width":768,"height":1376},"Created Date":"2026-09-28T1259:42.7204401Z","outputFormat":"jpeg","civitaiResources":[{"type":"diffusionmodel","weight":1,"modelVersionId":3072332},{"type":"lora","weight":1,"modelVersionId":3116962},{"type":"lora","weight":1,"modelVersionId":3210573}]}'::jsonb, TRUE, NULL, '2026-09-28T16:08:36.998Z'::timestamptz, '2026-09-28T21:11:51.321Z'::timestamptz),
(143827469, 31242930, NULL, 'ducktopuss', 'https://image.civitai.com/xG1nkqKTMzGDvpLrqFT7WA/1d6023c7-7e0a-4f77-8e09-881ead544f56/original=true/1d6023c7-7e0a-4f77-8e09-881ead544f56.jpeg', 'civitai_collector/data/images/143827469.webp', 1024, 1536, 'None', 'image', 'USFrFs-o={X8~qxZt6xZb_ofIpWBAII;Rjt7', '<lora:duckymix_krea2_epoch_10_lora_f16:1>,, A cinematic anime illustration with soft painterly rendering and atmospheric perspective, shot from the side during golden hour. Two schoolgirls sit back-to-back on the edge of a high rooftop, their legs dangling casually over the side into empty space above a sprawling city below. The taller girl on the left has short messy silver hair windswept and tousled, a tired weary expression on her face with half-lidded eyes showing exhaustion, wearing a rumpled school uniform with the blazer wrinkled, white shirt untucked, and red tie loosened and hanging askew around her neck. She holds a cold can of coffee in one hand, condensation visible on the aluminum. The shorter girl on the right has long black hair styled in neat twin braids that the wind tugs at, round wire-frame glasses perched on her nose, a small content smile playing on her lips, and wears an oversized grey hoodie pulled over her school uniform that''s several sizes too big with the sleeves covering her hands. She holds a worn paperback book open in her lap, pages fluttering slightly in the breeze. They sit with their backs pressed together for support, creating a moment of quiet companionship. The city sprawls far below them bathed in warm orange and golden light from the setting sun, buildings creating geometric patterns of light and shadow, distant radio towers with blinking red lights rising from the urban landscape, and scattered fluffy clouds in the sky catching pink and amber hues. Strong wind visibly pulls at their hair and clothes, the silver-haired girl''s tie flapping, strands of the braided girl''s hair escaping, and the hoodie rippling. Warm sunset light bathes the scene from the side creating long shadows and golden rim lighting on their silhouettes, with atmospheric lens flare from the sun creating soft glowing spots and halos. The atmospheric perspective shows the city fading into hazy blue-purple distance. The overall aesthetic combines slice-of-life anime storytelling with cinematic golden hour photography, emphasizing the peaceful moment of friendship, the contrast between the tired restless energy and calm contentment, and the beauty of the urban sunset viewed from above.', NULL, 'krea_2_turbo_q8', NULL, 'Euler A Trailing', 8, 1, 37832037, '2026-09-28T16:05:00.000Z'::timestamptz, '925d2df2600c12573f945cc08e2a11c26b13c2329cae8aebebdbb6df3e983410', '{"Size":"","seed":37832037,"Model":"krea_2_turbo_q8","steps":8,"hashes":{"model":"3b1b996998"},"prompt":"<lora:duckymix_krea2_epoch_10_lora_f16:1>,, A cinematic anime illustration with soft painterly rendering and atmospheric perspective, shot from the side during golden hour. Two schoolgirls sit back-to-back on the edge of a high rooftop, their legs dangling casually over the side into empty space above a sprawling city below. The taller girl on the left has short messy silver hair windswept and tousled, a tired weary expression on her face with half-lidded eyes showing exhaustion, wearing a rumpled school uniform with the blazer wrinkled, white shirt untucked, and red tie loosened and hanging askew around her neck. She holds a cold can of coffee in one hand, condensation visible on the aluminum. The shorter girl on the right has long black hair styled in neat twin braids that the wind tugs at, round wire-frame glasses perched on her nose, a small content smile playing on her lips, and wears an oversized grey hoodie pulled over her school uniform that''s several sizes too big with the sleeves covering her hands. She holds a worn paperback book open in her lap, pages fluttering slightly in the breeze. They sit with their backs pressed together for support, creating